package dev.bennett.codexmeter;
import java.util.*;import org.json.*;
public final class AchievementJourneySelfTest {
    static int count;static void check(boolean yes,String label){count++;if(!yes)throw new AssertionError(label);}
    static final String ACCOUNT="a".repeat(64);
    static void token(JSONObject d,long total,long at)throws Exception {RpgEngine.ingestOfficial(d,ACCOUNT,new JSONObject().put("account",ACCOUNT).put("source","codex_account_usage_v1").put("at",at).put("summary",new JSONObject().put("lifetimeTokens",total)),at);}
    public static void main(String[] args)throws Exception {
        long start=java.time.LocalDate.of(2026,10,12).atTime(12,0).atZone(LedgerAggregation.ZONE).toInstant().toEpochMilli();JSONObject d=AccountProgress.empty();token(d,100_000_000,start-1000);JSONObject s=RpgEngine.state(d);long xp=s.getLong("xp");String legacy=s.getJSONObject("achievements").toString();JSONObject old=RpgEngine.export(d,ACCOUNT);
        check(!RpgGrowthFacts.earned(s).isEmpty(),"Legacy automatic awards reproduce reported problem");check(AchievementJourney.prepare(d,start),"One-time opt-in migration");check(!AchievementJourney.enabled(s),"Default OFF");check(s.getLong("xp")==xp,"XP not reset");check(RpgGrowthFacts.earned(s).isEmpty(),"Old collection reset");check(AchievementJourney.journey(s).getJSONObject("legacy").getJSONObject("achievements").toString().equals(legacy),"Full old award evidence archived");check(!AchievementJourney.prepare(d,start+1),"Repeated migration does not reset again");
        token(d,200_000_000,start+1000);check(RpgGrowthFacts.earned(s).isEmpty(),"OFF does not auto-award historical or new tokens");check(AchievementJourney.setEnabled(d,true,start+2000),"Explicit start");String id=AchievementJourney.journey(s).getString("id");token(d,300_000_000,start+3000);check(AchievementJourney.journey(s).getLong("tokens")==0,"First observation establishes baseline");token(d,301_000_000,start+4000);check(AchievementJourney.journey(s).getLong("tokens")==1_000_000,"Only new delta counts");check(RpgGrowthFacts.earned(s).contains("tokens_1000000"),"New token medal earned");long earnedAt=s.getJSONObject("achievements").getJSONObject("tokens_1000000").getLong("first_earned_at");token(d,301_000_000,start+5000);check(AchievementJourney.journey(s).getLong("tokens")==1_000_000,"Duplicate counter does not double count");
        AchievementJourney.setEnabled(d,false,start+6000);token(d,20_000_000_000L,start+7000);check(AchievementJourney.journey(s).getLong("tokens")==1_000_000,"OFF pauses counting");check(RpgGrowthFacts.earned(s).contains("tokens_1000000"),"OFF preserves earned medals");AchievementJourney.setEnabled(d,true,start+8000);check(AchievementJourney.journey(s).getString("id").equals(id),"Resume never creates a new/reset journey");token(d,21_000_000_000L,start+9000);check(AchievementJourney.journey(s).getLong("tokens")==1_000_000,"Paused token work is excluded");token(d,21_001_000_000L,start+10000);check(AchievementJourney.journey(s).getLong("tokens")==2_000_000,"Resume adds only new verified delta");check(s.getJSONObject("achievements").getJSONObject("tokens_1000000").getLong("first_earned_at")==earnedAt,"First earned date permanent");
        long reset=start+TierEvolution.WEEK;List<LedgerRecord> rows=Arrays.asList(new LedgerRecord("weekly","pro",start+7999,40,"40",reset,604800,"api_precise",false),new LedgerRecord("weekly","pro",start+8100,50,"50",reset,604800,"api_precise",false));AchievementJourney.capture(d,rows,Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),start+12000);check(AchievementJourney.journey(s).getJSONObject("activity").length()==0,"Pair crossing resume boundary excluded");
        rows=Arrays.asList(rows.get(1),new LedgerRecord("weekly","pro",start+11000,60,"60",reset,604800,"api_precise",false));AchievementJourney.capture(d,rows,Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),start+12000);check(AchievementJourney.metrics(s,true).get("days")==1,"Measured post-start activity counted");AchievementJourney.capture(d,rows,Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),start+12000);check(AchievementJourney.metrics(s,true).get("days")==1,"Same day/pair never counted twice");
        RpgEngine.merge(d,ACCOUNT,old,start+13000);s=RpgEngine.state(d);check(!RpgGrowthFacts.earned(s).contains("tokens_10000000")&&!RpgGrowthFacts.earned(s).contains("tokens_100000000"),"Old backup cannot resurrect reset token medals");List<String> retained=new ArrayList<>(RpgGrowthFacts.earned(s));check(s.getLong("xp")>=xp,"Restore cannot lower XP");JSONObject copy=new JSONObject(d.toString());check(AchievementJourney.journey(RpgEngine.state(copy)).getString("id").equals(id),"Journal restart preserves journey ID");JSONObject journal=RpgEngine.export(d,ACCOUNT),other=AccountProgress.empty();check(RpgEngine.merge(other,ACCOUNT,journal,start+15000),"Same-account journey journal portable");check(RpgGrowthFacts.earned(RpgEngine.state(other)).equals(retained),"Portable earned collection retained");check(!RpgEngine.merge(other,"b".repeat(64),journal,start+15000),"Foreign account rejected");
        System.out.println("Achievement opt-in: "+count+" meaningful checks passed; synthetic evidence only.");
    }
}
